import{_ as s,o as n,c as e,N as o}from"./chunks/framework.CM5G1ysn.js";const u=JSON.parse('{"title":"Kafka 与 Outbox：把业务提交和通知投递衔接起来","description":"用申请批准后的通知串起本地事务、Outbox、Kafka 消费进度和业务幂等，理解 AFTER_COMMIT 与可靠投递的区别。","frontmatter":{"title":"Kafka 与 Outbox：把业务提交和通知投递衔接起来","date":"2026-11-06T00:00:00.000Z","description":"用申请批准后的通知串起本地事务、Outbox、Kafka 消费进度和业务幂等，理解 AFTER_COMMIT 与可靠投递的区别。","category":"Java 后端","tags":["Kafka","Outbox","Spring","消息队列","幂等"],"folder":"java/highlights"},"headers":[{"level":2,"title":"一笔数据库事务包不住两个系统","slug":"一笔数据库事务包不住两个系统","link":"#一笔数据库事务包不住两个系统","children":[]},{"level":2,"title":"Outbox 先把待发送事件和业务一起保存","slug":"outbox-先把待发送事件和业务一起保存","link":"#outbox-先把待发送事件和业务一起保存","children":[]},{"level":2,"title":"发送确认和 SENT 状态之间仍可能重发","slug":"发送确认和-sent-状态之间仍可能重发","link":"#发送确认和-sent-状态之间仍可能重发","children":[]},{"level":2,"title":"先提交通知数据库，再提交 Offset","slug":"先提交通知数据库再提交-offset","link":"#先提交通知数据库再提交-offset","children":[]},{"level":2,"title":"AFTER_COMMIT 保证执行时机，不提供持久化队列","slug":"after_commit-保证执行时机不提供持久化队列","link":"#after_commit-保证执行时机不提供持久化队列","children":[]},{"level":2,"title":"参考与来源","slug":"参考与来源","link":"#参考与来源","children":[]}],"relativePath":"posts/kafka-outbox-notifications.md","filePath":"posts/kafka-outbox-notifications.md"}'),l={name:"posts/kafka-outbox-notifications.md"};function p(t,a,c,r,i,d){return n(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="kafka-与-outbox把业务提交和通知投递衔接起来" tabindex="-1">Kafka 与 Outbox：把业务提交和通知投递衔接起来 <a class="header-anchor" href="#kafka-与-outbox把业务提交和通知投递衔接起来" aria-label="Permalink to &quot;Kafka 与 Outbox：把业务提交和通知投递衔接起来&quot;">​</a></h1><p>批准一条申请后，系统需要修改申请状态、增加成员，并通知申请人。直接在一个数据库事务里完成这些写入，适合许多简单场景；引入 Kafka 后，通知处理可以独立进行，但同时出现了一个问题：数据库提交和消息发送如何衔接？</p><p>下面从学习笔记中的通知场景抽象出一条通用链路。代码和表结构均为示意，省略序列化、依赖配置与完整错误处理，不代表一套可以直接运行的消息系统。</p><h2 id="一笔数据库事务包不住两个系统" tabindex="-1">一笔数据库事务包不住两个系统 <a class="header-anchor" href="#一笔数据库事务包不住两个系统" aria-label="Permalink to &quot;一笔数据库事务包不住两个系统&quot;">​</a></h2><p>先提交业务数据库，再发送消息，进程可能在两步之间停止，留下“申请通过但没有通知消息”的结果。若先发送消息，再提交数据库，又可能在数据库回滚后仍产生一条成功通知。</p><p>Kafka 发送并不会因为发生在 <code>@Transactional</code> 方法里，就自动加入普通 JDBC 事务。MySQL 回滚也无法把已经进入 Kafka 的消息撤回来。因此，需要把“记下需要通知这件事”和“实际发送通知消息”拆开。</p><h2 id="outbox-先把待发送事件和业务一起保存" tabindex="-1">Outbox 先把待发送事件和业务一起保存 <a class="header-anchor" href="#outbox-先把待发送事件和业务一起保存" aria-label="Permalink to &quot;Outbox 先把待发送事件和业务一起保存&quot;">​</a></h2><p>Outbox 是存放待发送事件的数据库表。业务事务除了更新业务数据，还插入一条事件记录：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>事务一：HTTP 请求线程</span></span>
<span class="line"><span>  修改申请状态</span></span>
<span class="line"><span>  增加项目成员</span></span>
<span class="line"><span>  插入 Outbox，状态为 PENDING</span></span>
<span class="line"><span>  → 一起提交或一起回滚</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后台 Relay</span></span>
<span class="line"><span>  读取待发送事件 → 发送 Kafka → 收到确认后标记 SENT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>消费者</span></span>
<span class="line"><span>  读取 Kafka → 写通知数据库 → 提交消费进度</span></span></code></pre></div><p>一条最小事件记录可以包含稳定的 <code>event_id</code>、事件类型、版本、正文和投递状态。消息正文保存处理通知所需的数据快照，让后续处理不必重新猜测业务发生时的内容。多次重试同一条事件，应继续使用同一个事件标识。</p><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">@</span><span style="color:#D73A49;">Transactional</span></span>
<span class="line"><span style="color:#D73A49;">public</span><span style="color:#D73A49;"> void</span><span style="color:#6F42C1;"> approve</span><span style="color:#24292E;">(ApproveCommand command) {</span></span>
<span class="line"><span style="color:#24292E;">    applicationMapper.</span><span style="color:#6F42C1;">markApproved</span><span style="color:#24292E;">(command.</span><span style="color:#6F42C1;">applicationId</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">    memberMapper.</span><span style="color:#6F42C1;">insert</span><span style="color:#24292E;">(</span><span style="color:#6F42C1;">buildMember</span><span style="color:#24292E;">(command));</span></span>
<span class="line"><span style="color:#24292E;">    outboxMapper.</span><span style="color:#6F42C1;">insert</span><span style="color:#24292E;">(</span><span style="color:#6F42C1;">buildPendingEvent</span><span style="color:#24292E;">(command));</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre></div><p>这里的关键是三个操作使用同一个本地事务。Outbox 写入失败时，业务也不能当作整体成功；业务提交成功后，数据库中则留下一条可供后台继续处理的待办。</p><h2 id="发送确认和-sent-状态之间仍可能重发" tabindex="-1">发送确认和 SENT 状态之间仍可能重发 <a class="header-anchor" href="#发送确认和-sent-状态之间仍可能重发" aria-label="Permalink to &quot;发送确认和 SENT 状态之间仍可能重发&quot;">​</a></h2><p>Relay 可以定时扫描 <code>PENDING</code> 事件。多个工作者并发时，需要通过合适的锁定或领取机制避免无序争抢。学习示例可以在事务中锁定一条记录、发送并等待确认，再更新状态，但网络等待期间会占用数据库连接和锁；吞吐需求上来后，应重新评估领取状态、租约和批量处理设计。</p><p>即使做了这些，仍存在一个时间窗口：Kafka 已确认收到消息，Relay 却在提交 <code>SENT</code> 之前停止。恢复后，数据库中该事件仍是待发送状态，于是会再次发送。</p><p><code>enable.idempotence=true</code> 能约束生产者协议层面的特定重试重复，不能代替跨进程重启、跨数据库状态更新的业务去重。稳定的 Kafka 消息 key 也不意味着 Broker 会按这个 key 自动删除重复事件。</p><p>因此，这类设计应准备接收重复事件。Outbox 缩小了丢失待发送意图的窗口，但不等于端到端“恰好执行一次”。<code>SENT</code> 也只说明发送得到确认并记录了结果，不代表通知已经落库或被用户读到。</p><h2 id="先提交通知数据库再提交-offset" tabindex="-1">先提交通知数据库，再提交 Offset <a class="header-anchor" href="#先提交通知数据库再提交-offset" aria-label="Permalink to &quot;先提交通知数据库，再提交 Offset&quot;">​</a></h2><p>消费者需要在业务处理完成后确认消费进度。以下片段只演示单条、顺序处理的提交顺序；<code>saveIdempotently</code> 应在事务提交后才返回：</p><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">notificationWriter.</span><span style="color:#6F42C1;">saveIdempotently</span><span style="color:#24292E;">(event);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">TopicPartition partition </span><span style="color:#D73A49;">=</span></span>
<span class="line"><span style="color:#D73A49;">    new</span><span style="color:#6F42C1;"> TopicPartition</span><span style="color:#24292E;">(record.</span><span style="color:#6F42C1;">topic</span><span style="color:#24292E;">(), record.</span><span style="color:#6F42C1;">partition</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">consumer.</span><span style="color:#6F42C1;">commitSync</span><span style="color:#24292E;">(Map.</span><span style="color:#6F42C1;">of</span><span style="color:#24292E;">(</span></span>
<span class="line"><span style="color:#24292E;">    partition, </span><span style="color:#D73A49;">new</span><span style="color:#6F42C1;"> OffsetAndMetadata</span><span style="color:#24292E;">(record.</span><span style="color:#6F42C1;">offset</span><span style="color:#24292E;">() </span><span style="color:#D73A49;">+</span><span style="color:#005CC5;"> 1</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#24292E;">));</span></span></code></pre></div><p>显式管理进度时需关闭自动提交。提交的位置表示下次应读取的位置，因此处理完某条记录后，通常提交该记录的 <code>offset + 1</code>。批量或并行处理时，必须按分区确认连续完成的位置，不能因为后面的记录处理成功，就越过前面尚未成功的记录。</p><p>若先提交 Offset，再写数据库，崩溃可能使未完成的通知被跳过。反过来先写数据库，则可能在数据库提交后、Offset 提交前崩溃，恢复时重复处理。这正是消费者必须具备业务幂等的原因。</p><p>一种做法是为事件标识设置唯一约束，并在同一数据库事务内完成去重记录和通知写入。遇到重复时，应确认是预期事件已经成功处理；其他数据库异常不能一概吞掉，也不要因重试覆盖原通知的已读状态。处理失败后还需明确重试、暂停或恢复策略，不能在内存读取位置已经前移后直接继续跳过错误记录。</p><h2 id="after_commit-保证执行时机不提供持久化队列" tabindex="-1">AFTER_COMMIT 保证执行时机，不提供持久化队列 <a class="header-anchor" href="#after_commit-保证执行时机不提供持久化队列" aria-label="Permalink to &quot;AFTER_COMMIT 保证执行时机，不提供持久化队列&quot;">​</a></h2><p><code>@TransactionalEventListener(phase = AFTER_COMMIT)</code> 可以让监听器在业务事务成功提交后执行；默认没有事务时不会执行，除非启用 <code>fallbackExecution</code>。它适合表达“只有提交成功才做后续动作”。</p><p>但进程可能在数据库提交后、监听逻辑完成前停止，内存中的事件不会自动变成可恢复的待办。监听器也不会仅凭这个注解自动异步执行。若提交后还要写数据库，应通过适当的新事务边界执行，例如调用另一个 Bean 中声明 <code>REQUIRES_NEW</code> 的方法。</p><p>当需求进一步要求应用重启后仍可重试投递时，Outbox 才承担持久记录发送意图的职责。最终能否持续送达，还取决于 Relay 恢复、消费者故障处理、消息保留时间和运行监测等配套机制，不能由一张表或一个注解单独保证。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><p>本文整理自个人项目学习笔记，保留了三段处理流程与故障窗口的分析，移除了本地部署配置和源码路径。</p><ul><li><a href="https://docs.spring.io/spring-framework/reference/data-access/transaction/event.html" target="_blank" rel="noreferrer">Spring：绑定事务阶段的事件监听器</a></li><li><a href="https://kafka.apache.org/41/javadoc/org/apache/kafka/clients/consumer/KafkaConsumer.html" target="_blank" rel="noreferrer">KafkaConsumer：消费位置、手动提交与外部数据存储</a></li><li><a href="https://kafka.apache.org/41/javadoc/org/apache/kafka/clients/producer/KafkaProducer.html" target="_blank" rel="noreferrer">KafkaProducer：异步发送与生产者幂等的边界</a></li></ul>`,30)])])}const h=s(l,[["render",p]]);export{u as __pageData,h as default};
